def load_rows(path):
    with open(path) as fh:
        for line in fh:
            if line.strip():
                yield line.rstrip("\n").split(",")


def summarize(path):
    rows = load_rows(path)
    count = sum(1 for _ in rows)
    widths = [len(r) for r in rows]
    return count, max(widths, default=0)

